{
  "diagnoses": [
    {
      "preserve": "The tool customizes the beginning of a Git commit hash; the page describes hexadecimal characters and wildcard placeholders.",
      "problem": "“Simple” is an unsupported ease-of-use judgment, and “whatever you want” overstates the available prefix choices described later on the page.",
      "quote": "With this simple tool, you can change the start of your git commit hashes to whatever you want.",
      "segment_index": 0,
      "unit_ordinal": 3
    },
    {
      "preserve": "The tool repeatedly changes whitespace in commit messages until the hash satisfies the requested prefix.",
      "problem": "“Good hash” leaves the stopping condition vague even though the surrounding instructions define it as matching the requested prefix.",
      "quote": "keeps trying new messages until it finds a good hash.",
      "segment_index": 0,
      "unit_ordinal": 6
    },
    {
      "preserve": "Whether CPU performance is adequate depends on the intended use; retain the separate, laptop-specific measurement of about 20x slower.",
      "problem": "“There's a good chance” asserts an unspecified likelihood of acceptable performance, while the extended qualification never identifies a workload or adequacy threshold.",
      "quote": "but depending on what you're planning to use the tool for, there's a good chance it's fast enough anyway.",
      "segment_index": 0,
      "unit_ordinal": 36
    },
    {
      "preserve": "The older versions are slower than the current version and are unmaintained.",
      "problem": "“Drastically” assigns an unsupported magnitude to the slowdown. The page's CPU/GPU comparison does not establish performance differences for these older branches.",
      "quote": "Note that these older versions are drastically slower than the current version, and are also unmaintained.",
      "segment_index": 6,
      "unit_ordinal": 39
    },
    {
      "preserve": "SHA256 use is presented as uncommon, with uncertainty about any particular reader's repository.",
      "problem": "The reader's uncertainty is used as evidence of the repository's object format. The page's general rarity claim does not establish that inference.",
      "quote": "If you're wondering whether your repository uses sha256, then it probably doesn't.",
      "segment_index": 0,
      "unit_ordinal": 75
    },
    {
      "preserve": "At the time of writing, the feature is experimental and its use is described as rare.",
      "problem": "“Highly” and “very” amplify the maturity and adoption claims without supporting evidence; “experimental” was already established in the linked format description.",
      "quote": "At the time of writing, this is a highly experimental feature and is very rarely used.",
      "segment_index": 0,
      "unit_ordinal": 76
    }
  ],
